public final class JdbcCheckoutQuoteRepository implements CheckoutQuoteRepository {
 private final JdbcTemplate jdbc;private final Clock clock;private final Pricing pricing;private final MarketEligibility markets;private final PricingProviders providers;private final PriceAdjustments adjustments;private final FrozenPrices frozen;private final PricingAuthority authority;private final int ttl;
 public JdbcCheckoutQuoteRepository(JdbcTemplate jdbc,Clock clock,Pricing pricing,MarketEligibility markets,PricingProviders providers,PriceAdjustments adjustments,FrozenPrices frozen,PricingAuthority authority,int ttl){if(ttl<1||ttl>300)throw new IllegalArgumentException("QUOTE_TTL_INVALID");this.jdbc=jdbc;this.clock=clock;this.pricing=pricing;this.markets=markets;this.providers=providers;this.adjustments=adjustments;this.frozen=frozen;this.authority=authority;this.ttl=ttl;}
 private record Cart(long version,UUID market,UUID organization,String state){}
 private record CartItem(UUID sku,UUID product,BigDecimal quantity,int scale,BigDecimal pack,JsonNode packaging){}
 private record Carrier(UUID cart,long cartVersion,UUID market,String mode,String currency,BigDecimal amount,String addressHash,String packageHash,JsonNode packages,String service,Instant expires,String status,UUID revision,long version){}
 public void requireOwner(ActorAssertion.Actor actor,PricingValues.QuoteInput input){UUID party=actor.party();if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.cart WHERE id=? AND party_id=?) AND EXISTS(SELECT 1 FROM commerce.address WHERE id=? AND party_id=? AND deleted_at IS NULL)",Boolean.class,input.cartId(),party,input.addressId(),party)))throw new Problem.Failure(ProblemCode.NOT_FOUND);UUID organization=jdbc.queryForObject("SELECT organization_id FROM commerce.cart WHERE id=? AND party_id=?",UUID.class,input.cartId(),party);if(organization!=null)authority.organization(actor,organization,false);}
 public void requireReplay(ActorAssertion.Actor actor,UUID quote){var rows=jdbc.query("SELECT price_snapshot::text FROM commerce.checkout_quote WHERE id=?",(r,n)->EventCodec.JSON.readTree(r.getString(1)),quote);if(rows.size()!=1||!actor.party().toString().equals(rows.getFirst().path("partyId").asString()))throw new Problem.Failure(ProblemCode.NOT_FOUND);var org=rows.getFirst().get("organizationId");if(org!=null&&!org.isNull())authority.organization(actor,ApiValues.uuid(org.asString()),false);}
 public PricingValues.Quote create(ActorAssertion.Actor actor,PricingValues.QuoteInput input){UUID party=actor.party();Instant now=clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS),expires=now.plusSeconds(ttl);requireOwner(actor,input);var carts=jdbc.query("SELECT version,market_id,organization_id,status FROM commerce.cart WHERE id=? AND party_id=? FOR UPDATE",(r,n)->new Cart(r.getLong(1),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getString(4)),input.cartId(),party);if(carts.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var cart=carts.getFirst();if(!cart.state().equals("ACTIVE"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(cart.organization()!=null)authority.organization(actor,cart.organization(),true);
  var addresses=jdbc.query("SELECT recipient,phone,line1,line2,city,region,postal_code,country_code,organization_id FROM commerce.address WHERE id=? AND party_id=? AND deleted_at IS NULL FOR SHARE",(r,n)->new Object[]{new CarrierPacking.Address(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8)),r.getObject(9,UUID.class)},input.addressId(),party);if(addresses.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var address=(CarrierPacking.Address)addresses.getFirst()[0];UUID addressOrg=(UUID)addresses.getFirst()[1];if(addressOrg!=null&&!addressOrg.equals(cart.organization()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);
  var items=jdbc.query("SELECT l.sku_id,s.product_id,l.quantity,s.quantity_scale,s.pack_size,s.carrier_packaging::text FROM commerce.cart_line l JOIN commerce.sku s ON s.id=l.sku_id JOIN commerce.product p ON p.id=s.product_id WHERE l.cart_id=? AND s.active AND s.deleted_at IS NULL AND p.status='ACTIVE' AND p.deleted_at IS NULL ORDER BY p.id,s.id LIMIT 101 FOR SHARE OF p,s",(r,n)->new CartItem(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getBigDecimal(3),r.getInt(4),r.getBigDecimal(5),r.getString(6)==null?null:EventCodec.JSON.readTree(r.getString(6))),input.cartId());if(items.isEmpty()||items.size()>100)throw PricingValues.rule();var quantities=new LinkedHashMap<UUID,BigDecimal>();var products=new HashSet<UUID>();for(var item:items){if(quantities.putIfAbsent(item.sku(),item.quantity())!=null)throw PricingValues.rule();products.add(item.product());PricingValues.quantity(PricingValues.decimal(item.quantity()),item.scale());if(item.pack().signum()<=0||item.quantity().remainder(item.pack()).signum()!=0)throw PricingValues.rule();}
  var carriers=jdbc.query("SELECT * FROM commerce.carrier_quote WHERE id=? FOR SHARE",(r,n)->new Carrier(r.getObject("cart_id",UUID.class),r.getLong("cart_version"),r.getObject("market_id",UUID.class),r.getString("mode"),r.getString("currency_code"),r.getBigDecimal("delivery_amount"),r.getString("address_hash"),r.getString("package_hash"),EventCodec.JSON.readTree(r.getString("package_snapshot")),r.getString("service_code"),r.getTimestamp("expires_at").toInstant(),r.getString("status"),r.getObject("source_quote_revision_id",UUID.class),r.getLong("version")),input.carrierQuoteId());if(carriers.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var carrier=carriers.getFirst();var proof=providers.require(carrier.mode());if(!carrier.cart().equals(input.cartId())||carrier.cartVersion()!=cart.version()||!carrier.market().equals(cart.market())||!carrier.currency().equals("NGN")||!carrier.status().equals("QUOTED")||carrier.service()==null||!carrier.service().matches("[A-Z][A-Z0-9_]{0,79}")||!carrier.expires().isAfter(now)||!carrier.addressHash().equals(CarrierPacking.hash(address)))throw PricingValues.rule();var parcels=CarrierPacking.pack(items.stream().map(i->new CarrierPacking.Item(i.sku(),i.quantity(),i.scale(),i.packaging())).toList());String packagesHash=CarrierPacking.hash(parcels);if(!packagesHash.equals(carrier.packageHash())||!packagesHash.equals(EventCodec.hash(carrier.packages())))throw PricingValues.rule();if(carrier.expires().isBefore(expires))expires=carrier.expires();if(proof.validUntil().isBefore(expires))expires=proof.validUntil();
  // Market expects the existing closed Party address shape; carrier hashing uses its separate DTO above.
  var partyAddress=new LinkedHashMap<String,Object>();partyAddress.put("recipient",address.recipient());partyAddress.put("phone",address.phone());partyAddress.put("line1",address.line1());partyAddress.put("line2",address.line2());partyAddress.put("city",address.city());partyAddress.put("region",address.region());partyAddress.put("postalCode",address.postalCode());partyAddress.put("countryCode",address.countryCode());partyAddress.put("label","Checkout snapshot");partyAddress.put("isDefault",false);var sale=markets.require(cart.market(),address.countryCode(),products,EventCodec.JSON.valueToTree(partyAddress),proof);
  var prices=new LinkedHashMap<UUID,Pricing.Resolved>();var amounts=new LinkedHashMap<UUID,BigDecimal>();BigDecimal minimumOrder=BigDecimal.ZERO;FrozenPrices.Offer offer=null;if(carrier.revision()!=null){offer=frozen.require(carrier.revision(),party,cart.organization(),cart.market(),quantities,now);if(offer.validUntil().isBefore(expires))expires=offer.validUntil();for(var line:offer.lines())amounts.put(line.skuId(),PricingValues.rounded(line.quantity().multiply(line.unitAmount()),2));}else{for(var item:items){var value=pricing.resolve(item.sku(),item.quantity(),cart.market(),cart.organization(),now,expires,true);prices.put(item.sku(),value);amounts.put(item.sku(),PricingValues.rounded(value.quantity().multiply(value.unitAmount()),2));minimumOrder=minimumOrder.max(value.minimumOrderAmount());if(value.validUntil().isBefore(expires))expires=value.validUntil();}}
  BigDecimal delivery=PricingValues.minor(PricingValues.decimal(carrier.amount()),2);PriceAdjustments.Result discounts=offer==null?adjustments.quote(party,cart.organization(),cart.market(),input.couponCode(),amounts,delivery,now,expires):null;if(offer!=null&&input.couponCode()!=null)throw PricingValues.rule();if(discounts!=null&&discounts.validUntil().isBefore(expires))expires=discounts.validUntil();var lines=new ArrayList<PricingValues.Line>();var snapshots=new ArrayList<Map<String,Object>>();BigDecimal subtotal=BigDecimal.ZERO.setScale(2),discount=BigDecimal.ZERO.setScale(2),tax=BigDecimal.ZERO.setScale(2);for(var item:items){BigDecimal unit;PricingValues.Components values;var snapshot=new LinkedHashMap<String,Object>();if(offer!=null){var agreed=offer.lines().stream().filter(l->l.skuId().equals(item.sku())).findFirst().orElseThrow(PricingValues::rule);unit=PricingValues.minor(PricingValues.decimal(agreed.unitAmount()),2);var gross=amounts.get(item.sku());values=new PricingValues.Components(gross,PricingValues.minor(PricingValues.decimal(agreed.discount()),2),PricingValues.minor(PricingValues.decimal(agreed.tax()),2),PricingValues.rounded(gross.subtract(agreed.discount()).add(agreed.tax()),2));snapshot.put("sourceQuoteRevisionId",offer.revisionId());snapshot.put("sourceQuoteRevision",offer.revision());}else{var price=prices.get(item.sku());unit=price.unitAmount();values=PricingValues.components(item.quantity(),unit,discounts.lineDiscounts().get(item.sku()),sale.taxPolicy(),2);snapshot.put("priceBookId",price.bookId());snapshot.put("priceBookRevision",price.bookRevision());snapshot.put("minimumQuantity",PricingValues.decimal(price.minimumQuantity()));snapshot.put("packMultiple",PricingValues.decimal(price.packMultiple()));snapshot.put("minimumOrderAmount",price.minimumOrderAmount().toPlainString());snapshot.put("pricingContext",price.pricingContext());}subtotal=subtotal.add(values.subtotal());discount=discount.add(values.discount());tax=tax.add(values.tax());var line=new PricingValues.Line(item.sku(),PricingValues.decimal(item.quantity()),unit.toPlainString(),values.total().toPlainString());lines.add(line);snapshot.put("line",line);snapshot.put("subtotal",values.subtotal().toPlainString());snapshot.put("discount",values.discount().toPlainString());snapshot.put("tax",values.tax().toPlainString());snapshots.add(snapshot);}
  if(subtotal.subtract(discount).compareTo(minimumOrder)<0)throw PricingValues.rule();if(discounts!=null){BigDecimal deliveryDiscount=discounts.deliveryDiscount();if(deliveryDiscount==null||deliveryDiscount.signum()<0||deliveryDiscount.scale()>2||deliveryDiscount.compareTo(delivery)>0)throw PricingValues.rule();delivery=delivery.subtract(deliveryDiscount);}BigDecimal grand=PricingValues.rounded(subtotal.subtract(discount).add(tax).add(delivery),2);var totals=new PricingValues.Totals(PricingValues.rounded(subtotal,2).toPlainString(),PricingValues.rounded(discount,2).toPlainString(),PricingValues.rounded(tax,2).toPlainString(),delivery.toPlainString(),grand.toPlainString());expires=expires.truncatedTo(java.time.temporal.ChronoUnit.MICROS);if(!expires.isAfter(clock.instant()))throw PricingValues.rule();UUID id=EventCodec.uuid7(now);var commercial=new LinkedHashMap<String,Object>();commercial.put("schemaVersion",1);commercial.put("partyId",party);commercial.put("organizationId",cart.organization());commercial.put("cartId",input.cartId());commercial.put("cartVersion",cart.version());commercial.put("marketId",cart.market());commercial.put("marketRevision",sale.policyRevision());commercial.put("currency","NGN");commercial.put("taxPolicy",Map.of("schemaVersion",1,"mode",sale.taxPolicy().mode(),"rate",sale.taxPolicy().rate().toPlainString(),"rounding","HALF_UP","approvalReference",sale.taxPolicy().approvalReference()));commercial.put("returnsPolicyRevision",sale.returnsPolicyRevision());commercial.put("addressId",input.addressId());commercial.put("addressHash",carrier.addressHash());commercial.put("carrierQuoteId",input.carrierQuoteId());commercial.put("carrierQuoteVersion",carrier.version());commercial.put("carrierMode",carrier.mode());commercial.put("carrierService",carrier.service());commercial.put("packageHash",packagesHash);commercial.put("lines",snapshots);commercial.put("totals",totals);commercial.put("promotionRevisions",discounts==null?EventCodec.JSON.createArrayNode():discounts.revisions());commercial.put("expiresAt",expires);commercial.put("providerProof",proof);String hash=CarrierPacking.hash(commercial);jdbc.update("INSERT INTO commerce.checkout_quote(id,created_at,created_by,cart_id,cart_version,market_revision,address_snapshot,price_snapshot,quote_hash,expires_at,carrier_quote_id) VALUES (?,?,?,?,?,?,?::jsonb,?::jsonb,?,?,?)",id,java.sql.Timestamp.from(now),party.toString(),input.cartId(),cart.version(),sale.policyRevision(),EventCodec.JSON.writeValueAsString(address),EventCodec.JSON.writeValueAsString(commercial),hash,java.sql.Timestamp.from(expires),input.carrierQuoteId());return new PricingValues.Quote(id,cart.version(),"NGN",List.copyOf(lines),totals,hash,expires);
 }
}
